+    fn handle_visual_key(&mut self, key: UiKey, right_content: &str) -> Vec<UiAction> {
+        match key {
+            UiKey::Esc => {
+                self.clear_visual_selection();
+                self.mode = UiMode::Command;
+            }
+            UiKey::Char('v') => {
+                self.switch_visual_kind(VisualKind::Character, right_content);
+            }
+            UiKey::Char('V') => {
+                self.switch_visual_kind(VisualKind::Line, right_content);
+            }
+            UiKey::CtrlV => {
+                self.switch_visual_kind(VisualKind::Block, right_content);
+            }
+            UiKey::Char('h') | UiKey::Left => self.move_visual_cursor(0, -1, right_content),
+            UiKey::Char('j') | UiKey::Down => self.move_visual_cursor(1, 0, right_content),
+            UiKey::Char('k') | UiKey::Up => self.move_visual_cursor(-1, 0, right_content),
+            UiKey::Char('l') | UiKey::Right => self.move_visual_cursor(0, 1, right_content),
+            UiKey::Char('y') | UiKey::Char('Y') => {
+                self.yank_visual_selection(right_content);
+                self.clear_visual_selection();
+                self.mode = UiMode::Command;
+            }
+            _ => {}
+        }
+        Vec::new()
+    }
+
+    fn start_visual_selection(
+        &mut self,
+        kind: VisualKind,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) {
+        let pane = self.focus;
+        let cursor = self.start_position_for_pane(pane, right_content, right_cursor_column);
+        self.visual_selection = Some(VisualSelection {
+            pane,
+            kind,
+            anchor: cursor,
+            cursor,
+        });
+        self.pending = None;
+        self.mode = UiMode::Command;
+    }
+
+    fn switch_visual_kind(&mut self, kind: VisualKind, right_content: &str) {
+        let Some(mut selection) = self.visual_selection else {
+            return;
+        };
+        selection.kind = kind;
+        selection.cursor = self.clamp_position(selection.pane, selection.cursor, right_content);
+        selection.anchor = self.clamp_position(selection.pane, selection.anchor, right_content);
+        self.visual_selection = Some(selection);
+    }
+
+    fn move_visual_cursor(&mut self, row_delta: isize, column_delta: isize, right_content: &str) {
+        let Some(mut selection) = self.visual_selection else {
+            return;
+        };
+        let cursor = TextPosition {
+            row: selection.cursor.row.saturating_add_signed(row_delta),
+            column: selection.cursor.column.saturating_add_signed(column_delta),
+        };
+        selection.cursor = self.clamp_position(selection.pane, cursor, right_content);
+        self.visual_selection = Some(selection);
+    }
+
+    fn yank_visual_selection(&mut self, right_content: &str) {
+        let Some(selection) = self.visual_selection else {
+            return;
+        };
+        let lines = self.lines_for_pane(selection.pane, right_content);
+        self.set_yanked_text(selected_text(&lines, selection));
+    }
+
+    fn yank_focused_line(&mut self, right_content: &str, right_cursor_column: Option<usize>) {
+        let pane = self.focus;
+        let lines = self.lines_for_pane(pane, right_content);
+        if lines.is_empty() {
+            self.set_yanked_text(String::new());
+            return;
+        }
+        let position = self.start_position_for_pane(pane, right_content, right_cursor_column);
+        self.set_yanked_text(lines[position.row].clone());
+    }
+
+    fn set_yanked_text(&mut self, text: String) {
+        let count = text.chars().count();
+        self.yanked_text = Some(text);
+        self.show_status_notice(
+            format!("copied {count} chars"),
+            Duration::from_secs(STATUS_NOTICE_SECONDS),
+        );
+    }
+
+    fn clear_visual_selection(&mut self) {
+        self.visual_selection = None;
+    }
+
+    fn start_position_for_pane(
+        &self,
+        pane: PaneFocus,
+        right_content: &str,
+        right_cursor_column: Option<usize>,
+    ) -> TextPosition {
+        match pane {
+            PaneFocus::Left => self.clamp_position(
+                pane,
+                TextPosition {
+                    row: self.left_control_text_row(),
+                    column: 0,
+                },
+                right_content,
+            ),
+            PaneFocus::Right => {
+                let lines = self.lines_for_pane(pane, right_content);
+                let row = lines.len().saturating_sub(1);
+                let line_len = lines.get(row).map(|line| line.chars().count()).unwrap_or(0);
+                let column = right_cursor_column
+                    .unwrap_or(line_len)
+                    .min(line_len.saturating_sub(1));
+                TextPosition { row, column }
+            }
+        }
+    }
+
+    fn clamp_position(
+        &self,
+        pane: PaneFocus,
+        position: TextPosition,
+        right_content: &str,
+    ) -> TextPosition {
+        let lines = self.lines_for_pane(pane, right_content);
+        let row = position.row.min(lines.len().saturating_sub(1));
+        let line_len = lines.get(row).map(|line| line.chars().count()).unwrap_or(0);
+        let column = position.column.min(line_len.saturating_sub(1));
+        TextPosition { row, column }
+    }
+
+    fn lines_for_pane(&self, pane: PaneFocus, right_content: &str) -> Vec<String> {
+        match pane {
+            PaneFocus::Left => self.left_visual_lines(),
+            PaneFocus::Right => self
+                .visible_right_content(right_content)
+                .lines()
+                .map(str::to_string)
+                .collect(),
+        }
+    }
+
+    fn left_visual_lines(&self) -> Vec<String> {
+        let inner_width = usize::from(self.layout().left_width.saturating_sub(2).max(1));
+        self.left_widget_rows(inner_width)
+            .into_iter()
+            .map(|row| row.text)
+            .collect()
+    }
+
+    fn left_widget_rows(&self, inner_width: usize) -> Vec<LeftPaneRow> {
+        let mut rows = vec![LeftPaneRow {
+            text: if self.control_selected == 0 {
+                "> work-leaf  command".to_string()
+            } else {
+                "  work-leaf  command".to_string()
+            },
+            ready: false,
+        }];
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            let agent = &self.agents[*agent_index];
+            let selected = self.control_selected == visible_position + 1;
+            rows.push(LeftPaneRow {
+                text: compact_agent_row(agent, selected, inner_width),
+                ready: agent.ready,
+            });
+            if !agent.modified_files.is_empty() {
+                rows.push(LeftPaneRow {
+                    text: format!(
+                        "    files: {}",
+                        agent
+                            .modified_files
+                            .iter()
+                            .map(|path| path.display().to_string())
+                            .collect::<Vec<_>>()
+                            .join(", ")
+                    ),
+                    ready: false,
+                });
+            }
+            for (label, agents) in [
+                ("conflicts", &agent.conflicting_agents),
+                ("depends-on", &agent.depends_on),
+                ("depended-on-by", &agent.depended_on_by),
+            ] {
+                if !agents.is_empty() {
+                    rows.push(LeftPaneRow {
+                        text: format!(
+                            "    {label}: {}",
+                            agents
+                                .iter()
+                                .map(AgentId::as_str)
+                                .collect::<Vec<_>>()
+                                .join(", ")
+                        ),
+                        ready: false,
+                    });
+                }
+            }
+        }
+        rows
+    }
+
+    fn left_control_text_row(&self) -> usize {
+        if self.control_selected == 0 {
+            return 0;
+        }
+
+        let mut row = 1;
+        for (visible_position, agent_index) in self.visible_agent_indices().iter().enumerate() {
+            if self.control_selected == visible_position + 1 {
+                return row;
+            }
+            row += 1 + self.left_agent_detail_row_count(&self.agents[*agent_index]);
+        }
+        row.saturating_sub(1)
+    }
+
+    fn left_agent_detail_row_count(&self, agent: &AgentListEntry) -> usize {
+        usize::from(!agent.modified_files.is_empty())
+            + usize::from(!agent.conflicting_agents.is_empty())
+            + usize::from(!agent.depends_on.is_empty())
+            + usize::from(!agent.depended_on_by.is_empty())
+    }
+
+    fn right_spans(&self, right_content: &str) -> Vec<Spans<'static>> {
+        right_content
+            .lines()
+            .enumerate()
+            .map(|(row, line)| {
+                self.styled_line(PaneFocus::Right, row, line.to_string(), Style::default())
+            })
+            .collect()
+    }
+
+    fn styled_line(
+        &self,
+        pane: PaneFocus,
+        row: usize,
+        line: String,
+        base_style: Style,
+    ) -> Spans<'static> {
+        let Some(selection) = self
+            .visual_selection
+            .filter(|selection| selection.pane == pane)
+        else {
+            return Spans::from(vec![Span::styled(line, base_style)]);
+        };
+        let Some((start, end)) = selected_range_for_line(selection, row, line.chars().count())
+        else {
+            return Spans::from(vec![Span::styled(line, base_style)]);
+        };
+
+        let mut spans = Vec::new();
+        if start > 0 {
+            spans.push(Span::styled(char_slice(&line, 0, start), base_style));
+        }
+        if end > start {
+            spans.push(Span::styled(
+                char_slice(&line, start, end),
+                base_style.add_modifier(Modifier::REVERSED),
+            ));
+        }
+        if end < line.chars().count() {
+            spans.push(Span::styled(
+                char_slice(&line, end, line.chars().count()),
+                base_style,
+            ));
+        }
+        if spans.is_empty() {
+            spans.push(Span::styled(String::new(), base_style));
+        }
+        Spans::from(spans)
+    }
