+        .enumerate()
+        .filter_map(|(row, line)| {
+            selected_range_for_line(selection, row, line.chars().count())
+                .map(|(start, end)| char_slice(line, start, end))
+        })
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn selected_range_for_line(
+    selection: VisualSelection,
+    row: usize,
+    line_len: usize,
+) -> Option<(usize, usize)> {
+    match selection.kind {
+        VisualKind::Character => selected_character_range(selection, row, line_len),
+        VisualKind::Line => {
+            let first = selection.anchor.row.min(selection.cursor.row);
+            let last = selection.anchor.row.max(selection.cursor.row);
+            (first..=last).contains(&row).then_some((0, line_len))
+        }
+        VisualKind::Block => selected_block_range(selection, row, line_len),
+    }
+}
+
+fn selected_character_range(
+    selection: VisualSelection,
+    row: usize,
+    line_len: usize,
+) -> Option<(usize, usize)> {
+    let (start, end) = ordered_positions(selection.anchor, selection.cursor);
+    if row < start.row || row > end.row {
+        return None;
+    }
+
+    if line_len == 0 {
+        return Some((0, 0));
+    }
+
+    if start.row == end.row {
+        return Some((
+            start.column.min(line_len.saturating_sub(1)),
+            end.column.min(line_len.saturating_sub(1)).saturating_add(1),
+        ));
+    }
+
+    if row == start.row {
+        Some((start.column.min(line_len), line_len))
+    } else if row == end.row {
+        Some((0, end.column.min(line_len.saturating_sub(1)).saturating_add(1)))
+    } else {
+        Some((0, line_len))
+    }
+}
+
+fn selected_block_range(
+    selection: VisualSelection,
+    row: usize,
+    line_len: usize,
+) -> Option<(usize, usize)> {
+    let first_row = selection.anchor.row.min(selection.cursor.row);
+    let last_row = selection.anchor.row.max(selection.cursor.row);
+    if !(first_row..=last_row).contains(&row) {
+        return None;
+    }
+
+    let first_column = selection.anchor.column.min(selection.cursor.column);
+    let last_column = selection.anchor.column.max(selection.cursor.column);
+    let start = first_column.min(line_len);
+    let end = last_column.saturating_add(1).min(line_len);
+    Some((start, end))
+}
+
+fn ordered_positions(start: TextPosition, end: TextPosition) -> (TextPosition, TextPosition) {
+    if (start.row, start.column) <= (end.row, end.column) {
+        (start, end)
+    } else {
+        (end, start)
+    }
+}
